(()=>{if(window.PDFLib)return;const esc=s=>String(s||"").replace(/([\\()])/g,"\\$1").replace(/\r?\n/g," ");class P{constructor(doc,w,h){this.doc=doc;this.w=w;this.h=h;this.ops=[]}drawText(t,o={}){const x=o.x??40,y=o.y??40,s=o.size??11;this.ops.push(`BT /F1 ${s} Tf 1 0 0 1 ${x} ${y} Tm (${esc(t)}) Tj ET`)}}class D{constructor(){this.pages=[]}static async create(){return new D()}addPage(sz=[595,842]){const p=new P(this,sz[0],sz[1]);this.pages.push(p);return p}async embedFont(){return{}}async save(){const objs=[];const add=x=>{objs.push(x);return objs.length};const fontId=add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");const pagesKids=[];for(const p of this.pages){const content=p.ops.join("\n")||"BT /F1 11 Tf 1 0 0 1 40 800 Tm (Document vide) Tj ET";const contentId=add(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);const pageId=add(`<< /Type /Page /Parent 0 0 R /MediaBox [0 0 ${p.w} ${p.h}] /Contents ${contentId} 0 R /Resources << /Font << /F1 ${fontId} 0 R >> >> >>`);pagesKids.push(pageId)}const pagesId=add(`<< /Type /Pages /Count ${pagesKids.length} /Kids [${pagesKids.map(id=>`${id} 0 R`).join(" ")}] >>`);objs.forEach((o,i)=>{objs[i]=o.replace("/Parent 0 0 R",`/Parent ${pagesId} 0 R`)});const catalogId=add(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);let out="%PDF-1.4\n";const offs=[0];objs.forEach((o,i)=>{offs[i+1]=out.length;out+=`${i+1} 0 obj\n${o}\nendobj\n`});const xref=out.length;out+=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;for(let i=1;i<=objs.length;i++)out+=`${String(offs[i]).padStart(10,"0")} 00000 n \n`;out+=`trailer\n<< /Size ${objs.length+1} /Root ${catalogId} 0 R >>\nstartxref\n${xref}\n%%EOF`;return new TextEncoder().encode(out)}}window.PDFLib={PDFDocument:D,StandardFonts:{Helvetica:"Helvetica"}}})();
